// ---------------------------------------------------------------------------
// Classic Analog — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'

const A = (p) => `images/${p}`

WatchFace({
  initView() {
    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Dial (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('classic/dial.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Dial AOD (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('classic/dial-aod.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour and minute hands (TIME_POINTER) — normal state
    ui.createWidget(ui.widget.TIME_POINTER, {
      hour_centerX: px(195),
      hour_centerY: px(225),
      hour_posX: px(8),
      hour_posY: px(107),
      hour_path: A('hour_hand.png'),
      minute_centerX: px(195),
      minute_centerY: px(225),
      minute_posX: px(6),
      minute_posY: px(162),
      minute_path: A('minute_hand.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour and minute hands (TIME_POINTER) — AOD (screen-off)
    ui.createWidget(ui.widget.TIME_POINTER, {
      hour_centerX: px(195),
      hour_centerY: px(225),
      hour_posX: px(8),
      hour_posY: px(107),
      hour_path: A('hour_hand.png'),
      minute_centerX: px(195),
      minute_centerY: px(225),
      minute_posX: px(6),
      minute_posY: px(162),
      minute_path: A('minute_hand.png'),
      show_level: ui.show_level.ONLY_AOD,
    })

    // Smooth second hand (IMG)
    W.smoothsec = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      angle: 1,
      center_x: px(195),
      center_y: px(225),
      src: A('smooth_second.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })


    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    // <smooth-second-hand>
    // Generated by the "Smooth second hand" preset: the watch turns the hand (anim_steps on prop.ANGLE). Each animation runs from the current angle
    // to the next SPAN mark (60 s: the end of the minute; its length is exactly the time left) and the next one starts just after it, from the real time, so the hand can
    // never run more than a few seconds off. The running animation is stopped (ANIM_STATUS) before another starts and when the screen goes off:
    // two animations on one hand fight each other (measured on a Bip 6: the hand jumped back a few seconds, and after wake-up it showed a stale angle).
    // If the animation is refused, the hand moves once a second instead. Do not edit between the markers; apply the preset again to refresh.
    {
      const G = globalThis, SPAN = 60000;     // 10000 was the length that worked on a Bip 6; 60000 is being compared (one restart a minute)
      let aid = null;
      const kill = () => {
        try { if (aid != null && W.smoothsec && ui.anim_status) W.smoothsec.setProperty(ui.prop.ANIM_STATUS, { anim_id: aid, anim_status: ui.anim_status.STOP }); } catch (e) {}
        aid = null;
      };
      const turn = () => {
        const h = W.smoothsec; if (!h) return 1000;
        const d = new Date(), ms = d.getSeconds() * 1000 + d.getMilliseconds(), left = SPAN - (ms % SPAN);
        kill();
        try {
          if (!ui.prop.ANIM) throw new Error('no ANIM');
          aid = h.setProperty(ui.prop.ANIM, { anim_steps: [{ anim_prop: ui.prop.ANGLE, anim_from: ms * 0.006, anim_to: (ms + left) * 0.006, anim_rate: 'linear', anim_duration: left, anim_offset: 0 }], anim_fps: 25, anim_repeat: 0 });     // 60 looked the same on a Bip 6, so the default stays
          return left + 3;
        } catch (e) {
          h.setProperty(ui.prop.ANGLE, Math.round(ms / 1000) * 6 % 360);
          return 1000 - (Date.now() % 1000) + 2;
        }
      };
      const loop = (g) => { if (g !== G.__ssGen) return; let n = 1000; try { n = turn(); } catch (e) {} try { setTimeout(() => loop(g), n); } catch (e) {} };
      const stop = () => { G.__ssGen = (G.__ssGen || 0) + 1; kill(); };
      const start = () => { stop(); loop(G.__ssGen); };
      start();
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { pause_call: stop, resume_call: start });
    }
    // </smooth-second-hand>
  },

  build() {
    this.initView()
  },
})
